text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Lucy. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Lucy, I am so frustrated. My current data plan is just not enough for my needs and I keep running out of data halfway through the month. It is incredibly annoying!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am very sorry to hear that you have been experiencing this frustration with your data limits. I can certainly help you find a better plan.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "customer",
      "text": "Thank you. I just want something with more data so I don't have to worry about it anymore.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I can definitely look into that for you. Before we discuss your account details, could you please provide your account number and date of birth?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yes, my account number is 97853442 and my date of birth is 21/02/1967.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you, Sneha Khan. I see your current plan. I recommend the Unlimited Data Plus plan, which will give you all the data you need.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "That sounds perfect. How much will that cost me per month?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The new monthly price will be 55 dollars, and the change will take effect on the first day of your next billing cycle, which is October 1st.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "That is a fair price. Please go ahead and change it for me.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will process the plan change now and send a confirmation SMS to your phone number 93185 40283.",
      "tags": [
        "action:plan_change"
      ]
    },
    {
      "speaker": "customer",
      "text": "Great, thank you so much for your help, Lucy. I feel much better about this now.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "You are very welcome. Is there anything else I can assist you with today? I have updated your plan and you will receive that SMS shortly. Goodbye!",
      "tags": [
        "closure"
      ]
    }
  ]
}
